/**
 * Sky events judged from one observing site.
 *
 * `server/data/sky-events.json` holds every global event from 2026 to 2036 (Moon phases, showers, eclipses, oppositions,
 * conjunctions, elongations, equinoxes and solstices), generated by `spikes/direct-mode/sky-events/gen-sky-events.mts`.
 * Nothing in it depends on where you stand. This module adds the part that does: is the event above the horizon in the
 * dark, how high, at what time is it best, and how much the Moon gets in the way.
 *
 * NebulisDesktop carries the same file and a Swift port of this judgement, so a change to a rule here belongs there too.
 */
import SunCalc from 'suncalc';
import skyEventsJson from '../data/sky-events.json';
import { altAz, getNightWindow, type NightWindow } from './astroCalc.js';
import { localDateKey, timeZoneOrLocal, zonedDateTimeToUtc } from './timezone.js';
import { isRecord } from './typeGuards.js';

export const SKY_EVENT_KINDS = [
  'moonPhase', 'meteorShower', 'lunarEclipse', 'solarEclipse', 'opposition', 'conjunction', 'elongation', 'season',
] as const;
export type SkyEventKind = (typeof SKY_EVENT_KINDS)[number];

export type GearNeed = 'solarFilter' | 'wideLens' | 'planetaryMode';
export type Verdict = 'good' | 'marginal' | 'poor' | 'unknown';
export type MoonInterference = 'none' | 'some' | 'severe';

interface Position { body: string; ra: number; dec: number }

export interface RawSkyEvent {
  id: string;
  kind: SkyEventKind;
  title: string;
  peak: string;
  start?: string;
  end?: string;
  bodies: string[];
  details: Record<string, number | string>;
  positions: Position[];
}

interface SkyEventsFile {
  version: number;
  validFrom: string;
  validUntil: string;
  events: RawSkyEvent[];
}

export interface SkyEventLocal {
  verdict: Verdict;
  /** One plain sentence for the list row. */
  reason: string;
  /** When to look, ISO UTC. */
  bestTime?: string;
  altitudeDeg?: number;
  moonIllumination: number;
  moonInterference: MoonInterference;
  /** Hours of the dark window with no Moon in the way. Only worked out where the Moon decides the night. */
  moonFreeHours?: number;
  /** The evening (local yyyy-MM-dd) of the night this event belongs to. */
  night: string;
  /** Forecast score for that night, only while it is inside the forecast range. */
  forecastScore?: number;
}

export interface SkyEvent extends RawSkyEvent {
  local: SkyEventLocal;
  tips: string[];
  gearNeeds: GearNeed[];
}

export interface SkySite {
  latitude: number;
  longitude: number;
  timezone: string;
}

function loadFile(): SkyEventsFile {
  const file: unknown = skyEventsJson;
  if (!isRecord(file) || file.version !== 1 || !Array.isArray(file.events) || typeof file.validFrom !== 'string' || typeof file.validUntil !== 'string') {
    throw new Error('sky-events.json is not a version 1 events file');
  }
  return { version: 1, validFrom: file.validFrom, validUntil: file.validUntil, events: file.events as RawSkyEvent[] };
}

const FILE = loadFile();

export function skyEventsRange(): { validFrom: string; validUntil: string } {
  return { validFrom: FILE.validFrom, validUntil: FILE.validUntil };
}

const STEP_MS = 10 * 60 * 1000;
const HOUR = 3_600_000;
/** Below this Sun altitude the sky is dark enough for anything but the brightest sights. */
const DARK_SUN_ALT = -3;

const toDeg = (r: number) => (r * 180) / Math.PI;

function clock(d: Date, tz: string): string {
  return new Intl.DateTimeFormat('en-US', { hour: 'numeric', minute: '2-digit', timeZone: timeZoneOrLocal(tz) }).format(d);
}

function round(x: number, places = 0): number {
  const f = 10 ** places;
  return Math.round(x * f) / f;
}

/** The evening that starts the night `t` belongs to: noon-to-noon, so 2 AM belongs to the evening before. */
export function nightKeyOf(t: Date, tz: string): string {
  return localDateKey(new Date(t.getTime() - 12 * HOUR), tz);
}

function sunAlt(t: Date, s: SkySite): number {
  return toDeg(SunCalc.getPosition(t, s.latitude, s.longitude).altitude);
}

function moonAlt(t: Date, s: SkySite): number {
  return toDeg(SunCalc.getMoonPosition(t, s.latitude, s.longitude).altitude);
}

/** Altitude of one of an event's bodies. The Moon moves too far in a night to be held at its peak position. */
function bodyAlt(p: Position, t: Date, s: SkySite): number {
  return p.body === 'Moon' ? moonAlt(t, s) : altAz(p.ra, p.dec, s.latitude, s.longitude, t).alt;
}

function moonInterferenceAt(t: Date, s: SkySite): { illumination: number; level: MoonInterference } {
  const illumination = round(SunCalc.getMoonIllumination(t).fraction * 100);
  if (moonAlt(t, s) <= 5) return { illumination, level: 'none' };
  return { illumination, level: illumination >= 60 ? 'severe' : illumination >= 15 ? 'some' : 'none' };
}

interface Best { time: Date; altitude: number }

/** The moment in [from, to] where `score` is highest, sampled every ten minutes. */
function bestWithin(from: Date, to: Date, score: (t: Date) => number | null): Best | null {
  let best: Best | null = null;
  for (let ms = from.getTime(); ms <= to.getTime(); ms += STEP_MS) {
    const t = new Date(ms);
    const v = score(t);
    if (v !== null && (best === null || v > best.altitude)) best = { time: t, altitude: v };
  }
  return best;
}

interface Night { window: NightWindow; key: string }

function nightFor(t: Date, s: SkySite): Night {
  const key = nightKeyOf(t, s.timezone);
  return { key, window: getNightWindow(zonedDateTimeToUtc(key, { hour: 12 }, s.timezone), s.latitude, s.longitude) };
}

interface Judgement {
  verdict: Verdict;
  reason: string;
  best?: Best;
  interferenceAt?: Date;
  moonFreeHours?: number;
  /** Set when the best moment belongs to a different night than the event's peak does. */
  nightOf?: Date;
}

function byAltitude(alt: number, good: number, marginal: number): Verdict {
  return alt >= good ? 'good' : alt >= marginal ? 'marginal' : 'poor';
}

/** A Moon that lights the sky: above the horizon and not a thin crescent. */
function moonlit(t: Date, s: SkySite): boolean {
  return moonAlt(t, s) > 5 && SunCalc.getMoonIllumination(t).fraction * 100 >= 15;
}

function darkSpan(w: NightWindow): { from: Date; to: Date } | null {
  const from = w.nightStart ?? w.nauticalDusk ?? w.sunset, to = w.nightEnd ?? w.nauticalDawn ?? w.sunrise;
  return from && to && to > from ? { from, to } : null;
}

function moonFreeHoursIn(from: Date, to: Date, s: SkySite): number {
  let n = 0;
  for (let ms = from.getTime(); ms <= to.getTime(); ms += STEP_MS) if (!moonlit(new Date(ms), s)) n++;
  return round((n * STEP_MS) / HOUR, 1);
}

function judgeShower(e: RawSkyEvent, n: Night, s: SkySite): Judgement {
  const radiant = e.positions[0];
  const span = darkSpan(n.window);
  if (!radiant || !span) return { verdict: 'unknown', reason: 'There is no dark sky at this latitude that night.' };
  const alt = (t: Date) => altAz(radiant.ra, radiant.dec, s.latitude, s.longitude, t).alt;
  const moonFreeHours = moonFreeHoursIn(span.from, span.to, s);

  // The best moment is the radiant's highest, but only counted while the Moon is out of the sky: a radiant that peaks as the
  // Moon sets, minutes before dawn, is not a Moon-free night.
  const free = bestWithin(span.from, span.to, (t) => (moonlit(t, s) ? null : alt(t)));
  const any = bestWithin(span.from, span.to, alt);
  if (!any) return { verdict: 'unknown', reason: 'There is no dark sky at this latitude that night.' };

  if (free && free.altitude >= 15) {
    const base = `The radiant reaches ${Math.round(free.altitude)}° around ${clock(free.time, s.timezone)}, with the Moon down.`;
    const short = moonFreeHours < 1;
    const verdict = short ? 'marginal' : byAltitude(free.altitude, 40, 25);
    const moonUp = round((span.to.getTime() - span.from.getTime()) / HOUR - moonFreeHours, 1);
    const note = short ? ` Only ${Math.round(moonFreeHours * 60)} minutes of the dark are Moon-free.` : moonUp >= 1 ? ` The Moon is up for ${moonUp} hours of the dark.` : '';
    return { verdict, reason: base + note, best: free, interferenceAt: free.time, moonFreeHours };
  }
  const moon = moonInterferenceAt(any.time, s);
  const base = `The radiant reaches ${Math.round(any.altitude)}° around ${clock(any.time, s.timezone)}`;
  if (any.altitude < 15) return { verdict: 'poor', reason: `${base}. That is too low for a good show.`, best: any, interferenceAt: any.time, moonFreeHours };
  return { verdict: moon.level === 'none' ? byAltitude(any.altitude, 40, 25) : 'marginal',
           reason: `${base}, but the ${moon.illumination}% Moon is in the sky then and will drown out the fainter meteors.`, best: any, interferenceAt: any.time, moonFreeHours };
}

function judgeBodiesInDark(e: RawSkyEvent, n: Night, s: SkySite, good: number, marginal: number): Judgement {
  const w = n.window;
  if (!w.sunset || !w.sunrise) return { verdict: 'unknown', reason: 'The Sun does not set and rise normally here that night.' };
  const best = bestWithin(w.sunset, w.sunrise, (t) =>
    sunAlt(t, s) > DARK_SUN_ALT ? null : Math.min(...e.positions.map((p) => bodyAlt(p, t, s))));
  if (!best) return { verdict: 'poor', reason: 'It never gets dark enough to see this from here that night.' };
  const when = `around ${clock(best.time, s.timezone)}`;
  if (best.altitude <= 0) return { verdict: 'poor', reason: `It is below the horizon while the sky is dark.`, best, interferenceAt: best.time };
  let verdict = byAltitude(best.altitude, good, marginal);
  let reason = best.altitude < 3 ? `It is barely above the horizon ${when}.` : `It reaches ${Math.round(best.altitude)}° ${when}.`;
  let moonFreeHours: number | undefined;
  const span = darkSpan(w);
  if (isFaint(e) && span) {
    moonFreeHours = moonFreeHoursIn(span.from, span.to, s);
    const moon = moonInterferenceAt(best.time, s);
    if (moon.level === 'severe') {
      if (verdict === 'good') verdict = 'marginal';
      reason += ` The ${moon.illumination}% Moon is up then and will wash out a faint target.`;
    }
  }
  return { verdict, reason, best, interferenceAt: best.time, moonFreeHours };
}

/** Altitude and azimuth (from north) of one of an event's bodies. */
function bodyAltAz(p: Position, t: Date, s: SkySite): { alt: number; az: number } {
  if (p.body !== 'Moon') return altAz(p.ra, p.dec, s.latitude, s.longitude, t);
  const m = SunCalc.getMoonPosition(t, s.latitude, s.longitude);
  // SunCalc measures azimuth from the south, westward.
  return { alt: toDeg(m.altitude), az: (toDeg(m.azimuth) + 180 + 360) % 360 };
}

function separationDeg(a: { alt: number; az: number }, b: { alt: number; az: number }): number {
  const r = Math.PI / 180;
  const c = Math.sin(a.alt * r) * Math.sin(b.alt * r) + Math.cos(a.alt * r) * Math.cos(b.alt * r) * Math.cos((a.az - b.az) * r);
  return toDeg(Math.acos(Math.max(-1, Math.min(1, c))));
}

/** Separations this close count as equal: two planets are fixed points, so theirs is the same at every moment bar rounding noise. */
const SAME_SEPARATION_DEG = 0.25;

/**
 * A pairing is only worth seeing while the two are still close. A Moon pairing at the peak minute is often in daylight
 * here, and the Moon covers half a degree an hour, so the rule is: among the dark moments within 14 hours of the peak when
 * both are up, find how close they get, then of the moments within a quarter degree of that, take the one where they are
 * highest, and say how far apart they are then.
 */
function judgeConjunction(e: RawSkyEvent, s: SkySite): Judgement {
  const [a, b] = e.positions;
  const peak = new Date(e.peak).getTime();
  const candidates: Array<{ time: Date; sep: number; alt: number }> = [];
  if (a && b) {
    for (let ms = peak - 14 * HOUR; ms <= peak + 14 * HOUR; ms += STEP_MS) {
      const t = new Date(ms);
      if (sunAlt(t, s) > DARK_SUN_ALT) continue;
      const pa = bodyAltAz(a, t, s), pb = bodyAltAz(b, t, s);
      const low = Math.min(pa.alt, pb.alt);
      if (low < 3) continue;
      candidates.push({ time: t, sep: separationDeg(pa, pb), alt: low });
    }
  }
  if (candidates.length === 0) return { verdict: 'poor', reason: 'They are not both above the horizon in a dark sky near the closest approach.' };
  const closest = Math.min(...candidates.map((c) => c.sep));
  let best = candidates[0];
  let found = false;
  for (const c of candidates) {
    if (c.sep > closest + SAME_SEPARATION_DEG) continue;
    if (!found || c.alt > best.alt) { best = c; found = true; }
  }
  const together = best.sep <= 5;
  const verdict = !together ? 'marginal' : byAltitude(best.alt, 20, 8);
  const reason = `${round(best.sep, 1)}° apart around ${clock(best.time, s.timezone)}, the closest while the sky is dark. Both are at least ${Math.round(best.alt)}° up.`;
  return { verdict, reason, best: { time: best.time, altitude: best.alt }, nightOf: best.time };
}

function judgeLunarEclipse(e: RawSkyEvent, s: SkySite): Judgement {
  const peak = new Date(e.peak);
  const from = new Date(e.start ?? e.peak), to = new Date(e.end ?? e.peak);
  const best = bestWithin(from, to, (t) => moonAlt(t, s));
  if (!best || best.altitude <= 0) return { verdict: 'poor', reason: 'The Moon is below the horizon for the whole eclipse from here.' };
  const atPeak = moonAlt(peak, s);
  if (atPeak > 10) return { verdict: 'good', reason: `The Moon is ${Math.round(atPeak)}° up at the middle of the eclipse.`, best: { time: peak, altitude: atPeak } };
  return { verdict: 'marginal', reason: `Only part of it is visible: the Moon is highest (${Math.round(best.altitude)}°) at ${clock(best.time, s.timezone)}.`, best };
}

function greatCircleKm(lat1: number, lon1: number, lat2: number, lon2: number): number {
  const r = Math.PI / 180;
  const a = Math.sin(((lat2 - lat1) * r) / 2) ** 2 + Math.cos(lat1 * r) * Math.cos(lat2 * r) * Math.sin(((lon2 - lon1) * r) / 2) ** 2;
  return 6371 * 2 * Math.asin(Math.min(1, Math.sqrt(a)));
}

/** Without local circumstances this only says whether the Sun is up and how far the greatest eclipse is. */
function judgeSolarEclipse(e: RawSkyEvent, s: SkySite): Judgement {
  const peak = new Date(e.peak);
  const sun = sunAlt(peak, s);
  const lat = e.details.peakLatitude, lon = e.details.peakLongitude;
  if (sun <= 0) return { verdict: 'poor', reason: 'The Sun is below the horizon here at the time of greatest eclipse.' };
  // A partial eclipse has no central point. The key is absent then, and coercing "absent" would measure to latitude 0, longitude 0.
  if (typeof lat !== 'number' || typeof lon !== 'number') return { verdict: 'unknown', reason: 'The Sun is up here. How much of the eclipse you see depends on where you are in its path.' };
  const km = Math.round(greatCircleKm(s.latitude, s.longitude, lat, lon) / 10) * 10;
  if (km < 2500) return { verdict: 'marginal', reason: `About ${km.toLocaleString('en-US')} km from the point of greatest eclipse. You may see a partial eclipse; check the path for totality.` };
  return { verdict: 'poor', reason: `About ${km.toLocaleString('en-US')} km from the point of greatest eclipse, so probably out of reach from here.` };
}

function judgeSeason(e: RawSkyEvent, s: SkySite): Judgement {
  const nw = getNightWindow(zonedDateTimeToUtc(nightKeyOf(new Date(e.peak), s.timezone), { hour: 12 }, s.timezone), s.latitude, s.longitude);
  if (!nw.sunset || !nw.sunrise) return { verdict: 'unknown', reason: 'The Sun does not set and rise normally here around then.' };
  const hours = (nw.sunrise.getTime() - nw.sunset.getTime()) / HOUR;
  return { verdict: 'unknown', reason: `The night is ${round(hours, 1)} hours long here, sunset to sunrise.` };
}

function judgeMoonPhase(e: RawSkyEvent): Judgement {
  const phase = Number(e.details.phase);
  const reason = phase === 0 ? 'The darkest nights of the month are the few around this one.'
    : phase === 2 ? 'A bright Moon washes out faint targets all night.'
      : 'The Moon is up for about half the night.';
  return { verdict: 'unknown', reason };
}

/** Planets this faint need a Moon-free sky, like a deep-sky target. */
function isFaint(e: RawSkyEvent): boolean {
  return e.kind === 'opposition' && Number(e.details.magnitude) > 5;
}

function judge(e: RawSkyEvent, s: SkySite): { j: Judgement; night: Night } {
  const peak = new Date(e.peak);
  const night = nightFor(peak, s);
  switch (e.kind) {
    case 'meteorShower': return { j: judgeShower(e, night, s), night };
    case 'opposition': return { j: judgeBodiesInDark(e, night, s, 45, 25), night };
    case 'elongation': return { j: judgeBodiesInDark(e, night, s, 20, 8), night };
    case 'conjunction': {
      const j = judgeConjunction(e, s);
      return { j, night: j.nightOf ? nightFor(j.nightOf, s) : night };
    }
    case 'lunarEclipse': return { j: judgeLunarEclipse(e, s), night };
    case 'solarEclipse': return { j: judgeSolarEclipse(e, s), night };
    case 'season': return { j: judgeSeason(e, s), night };
    case 'moonPhase': return { j: judgeMoonPhase(e), night };
  }
}

const TIPS: Record<SkyEventKind, (e: RawSkyEvent, s: SkySite) => string[]> = {
  meteorShower: () => [
    'No telescope needed. A wide lens on a tripod, pointed about 45° from the radiant, catches the trails.',
    'Give your eyes 20 minutes to adapt, and keep away from the Moon and from lights.',
  ],
  lunarEclipse: (e) => [
    e.details.type === 'penumbral'
      ? 'A penumbral eclipse is a faint shading, easy to miss by eye. A photo series shows it best.'
      : 'The Moon dims and turns red in totality. Shoot a series so you can pick the best frames.',
  ],
  solarEclipse: () => [
    'Never look at the Sun, or point a telescope or camera at it, without a certified solar filter.',
    'Fit the filter before the eclipse starts and keep it on until it ends, except during totality.',
  ],
  opposition: (e) => [
    isFaint(e)
      ? 'Faint and tiny. A telescope shows a small blue-green disc; wait for a Moon-free night.'
      : 'Closest and brightest of its year. Short exposures stacked from video suit planets best.',
  ],
  conjunction: (e) => [
    e.bodies.includes('Moon')
      ? 'A wide frame fits both. The Moon is far brighter, so expose for the planet and the Moon will clip.'
      : 'A wide field fits both objects in one frame. A phone on a tripod works.',
  ],
  elongation: (e) => [
    e.details.visibility === 'evening'
      ? 'Best seen just after sunset. It stays low, so find a clear western horizon.'
      : 'Best seen just before sunrise. It stays low, so find a clear eastern horizon.',
  ],
  moonPhase: (e) => (Number(e.details.phase) === 0
    ? ['Plan deep-sky targets for the nights around now.']
    : Number(e.details.phase) === 2
      ? ['Try the Moon itself, or a narrowband filter on bright nebulae.']
      : []),
  season: (e, s) => {
    if (!/solstice/.test(e.title)) return [];
    const june = /June/.test(e.title), north = s.latitude >= 0;
    return [(june === north) ? 'The shortest night of the year, so plan for less darkness.' : 'The longest night of the year, so there is room for a long session.'];
  },
};

const GEAR: Partial<Record<SkyEventKind, (e: RawSkyEvent) => GearNeed[]>> = {
  meteorShower: () => ['wideLens'],
  solarEclipse: () => ['solarFilter'],
  opposition: (e) => (isFaint(e) ? [] : ['planetaryMode']),
  conjunction: () => ['wideLens'],
};

export function judgeEvent(e: RawSkyEvent, s: SkySite): SkyEvent {
  const { j, night } = judge(e, s);
  const at = j.interferenceAt ?? j.best?.time ?? new Date(e.peak);
  const moon = moonInterferenceAt(at, s);
  const moonMatters = e.kind === 'meteorShower' || isFaint(e);
  const local: SkyEventLocal = {
    verdict: j.verdict,
    reason: j.reason,
    moonIllumination: moon.illumination,
    moonInterference: moonMatters ? moon.level : 'none',
    night: night.key,
  };
  if (j.moonFreeHours !== undefined) local.moonFreeHours = j.moonFreeHours;
  if (j.best) {
    local.bestTime = j.best.time.toISOString();
    local.altitudeDeg = round(j.best.altitude);
  }
  return { ...e, local, tips: TIPS[e.kind](e, s), gearNeeds: GEAR[e.kind]?.(e) ?? [] };
}

export interface ListOptions {
  from: Date;
  to: Date;
  kinds?: ReadonlySet<SkyEventKind>;
  site: SkySite;
}

/** Events whose peak, or whose span, falls in the range, each judged from the site. */
export function listSkyEvents(opts: ListOptions): SkyEvent[] {
  const lo = opts.from.getTime(), hi = opts.to.getTime();
  return FILE.events
    .filter((e) => {
      if (opts.kinds && !opts.kinds.has(e.kind)) return false;
      const start = new Date(e.start ?? e.peak).getTime(), end = new Date(e.end ?? e.peak).getTime();
      return end >= lo && start <= hi;
    })
    .map((e) => judgeEvent(e, opts.site));
}

/**
 * Attach the forecast score to events whose night is inside the forecast range. Takes the cached forecast as `unknown`
 * because the cache does; anything that is not a list of dated ratings changes nothing.
 */
export function withForecastScores(events: SkyEvent[], forecast: unknown): SkyEvent[] {
  if (!isRecord(forecast) || !Array.isArray(forecast.nightRatings)) return events;
  const scores = new Map<string, number>();
  for (const r of forecast.nightRatings) {
    if (isRecord(r) && typeof r.date === 'string' && typeof r.score === 'number') scores.set(r.date, r.score);
  }
  return events.map((e) => {
    const score = scores.get(e.local.night);
    return score === undefined ? e : { ...e, local: { ...e.local, forecastScore: score } };
  });
}
